set-variable.value:
@{
        var body = context.Response.Body == null ? string.Empty : context.Response.Body.As<string>(preserveContent: true);
        if (string.IsNullOrWhiteSpace(body))
        {
            return string.Empty;
        }

        var messages = new List<string>();
        var contentType = context.Response.Headers.GetValueOrDefault("Content-Type", "");
        if (contentType.StartsWith("text/event-stream", StringComparison.OrdinalIgnoreCase))
        {
            /* Decode SSE data frames, including multiline data, before extracting JSON text. */
            var data = new List<string>();
            foreach (var line in (body.Replace("\r\n", "\n").Replace("\r", "\n") + "\n\n").Split('\n'))
            {
                if (line.Length == 0)
                {
                    if (data.Count != 0)
                    {
                        var message = string.Join("\n", data);
                        if (message != "[DONE]")
                        {
                            messages.Add(message);
                        }
                        data.Clear();
                    }
                }
                else if (line.StartsWith("data:", StringComparison.Ordinal))
                {
                    var value = line.Substring(5);
                    data.Add(value.StartsWith(" ") ? value.Substring(1) : value);
                }
            }
        }
        else
        {
            messages.Add(body);
        }

        var pending = new List<JToken>();
        foreach (var message in messages)
        {
            try { pending.Add(JToken.Parse(message)); }
            catch { pending.Add(new JValue(message)); }
        }
        var text = new List<string>();
        /* Also decode JSON embedded in MCP text content, so escaped text is moderated. */
        for (var index = 0; index < pending.Count; index++)
        {
            var token = pending[index];
            if (token.Type == JTokenType.Object)
            {
                foreach (var property in ((JObject)token).Properties())
                {
                    pending.Add(property.Value);
                }
            }
            else if (token.Type == JTokenType.Array)
            {
                foreach (var child in (JArray)token) { pending.Add(child); }
            }
            else if (token.Type == JTokenType.String)
            {
                var value = (string)token;
                var trimmed = value.TrimStart();
                if (trimmed.StartsWith("{") || trimmed.StartsWith("["))
                {
                    try
                    {
                        pending.Add(JToken.Parse(value));
                        continue;
                    }
                    catch { }
                }
                text.Add(value);
            }
        }
        return string.Join("\n", text);
    }

@{
                    var text = (string)context.Variables["web-iq-safety-text"];
                    var offset = (int)context.Variables["web-iq-safety-offset"];
                    var length = Math.Min(10000, text.Length - offset);
                    if (offset + length < text.Length && char.IsHighSurrogate(text[offset + length - 1])) { length--; }
                    return text.Substring(offset, length);
                }

send-request.set-body:
@{
                        return new JObject(
                            new JProperty("text", (string)context.Variables["web-iq-safety-chunk"]),
                            new JProperty("categories", new JArray("Hate", "Sexual", "Violence", "SelfHarm")),
                            new JProperty("outputType", "FourSeverityLevels")
                        ).ToString(Newtonsoft.Json.Formatting.None);
                    }

set-variable.value:
@{
                    var response = (IResponse)context.Variables["web-iq-safety-response"];
                    if (response == null || response.StatusCode != 200) { return string.Empty; }
                    try
                    {
                        var analysis = response.Body.As<JObject>()["categoriesAnalysis"] as JArray;
                        var scores = JObject.Parse((string)context.Variables["web-iq-safety-scores"]);
                        foreach (var category in new [] { "Hate", "Sexual", "Violence", "SelfHarm" })
                        {
                            var item = analysis == null ? null : analysis.FirstOrDefault(x => (string)x["category"] == category);
                            if (item == null || item["severity"] == null || item["severity"].Type != JTokenType.Integer) { return string.Empty; }
                            var severity = (int)item["severity"];
                            if (severity != 0 && severity != 2 && severity != 4 && severity != 6) { return string.Empty; }
                            scores[category] = Math.Max((int?)scores[category] ?? 0, severity);
                        }
                        return scores.ToString(Newtonsoft.Json.Formatting.None);
                    }
                    catch { return string.Empty; }
                }

@{
                            var text = (string)context.Variables["web-iq-safety-text"];
                            var end = (int)context.Variables["web-iq-safety-offset"] + ((string)context.Variables["web-iq-safety-chunk"]).Length;
                            if (end == text.Length) { return end; }
                            var next = end - 200;
                            if (char.IsLowSurrogate(text[next])) { next--; }
                            return next;
                        }

fragment.set-body:
@{
        var body = context.Response.Body == null ? string.Empty : context.Response.Body.As<string>(preserveContent: true);
        if (string.IsNullOrWhiteSpace(body)) { return body; }
        var status = (string)context.Variables["web-iq-safety-status"];
        var telemetry = new JObject(
            new JProperty("status", status),
            new JProperty("scores", status == "analyzed" ? JObject.Parse((string)context.Variables["web-iq-safety-scores"]) : new JObject()),
            new JProperty("chunks", (int)context.Variables["web-iq-safety-chunks"]),
            new JProperty("latencyMs", (double)context.Variables["web-iq-safety-latency"]),
            new JProperty("requestId", context.RequestId.ToString())
        );
        var isSse = context.Response.Headers.GetValueOrDefault("Content-Type", "").StartsWith("text/event-stream", StringComparison.OrdinalIgnoreCase);
        var frames = isSse ? body.Replace("\r\n", "\n").Replace("\r", "\n").Split(new [] { "\n\n" }, StringSplitOptions.None) : new [] { body };
        for (var frameIndex = 0; frameIndex < frames.Length; frameIndex++)
        {
            var lines = frames[frameIndex].Split('\n');
            var payload = frames[frameIndex];
            if (isSse)
            {
                var data = new List<string>();
                foreach (var line in lines)
                {
                    if (line.StartsWith("data:", StringComparison.Ordinal))
                    {
                        var value = line.Substring(5);
                        data.Add(value.StartsWith(" ") ? value.Substring(1) : value);
                    }
                }
                if (data.Count == 0) { continue; }
                payload = string.Join("\n", data);
            }

            JToken document;
            try { document = JToken.Parse(payload); }
            catch { continue; }
            var objects = document.Type == JTokenType.Array ? ((JArray)document).OfType<JObject>().ToList() : new List<JObject>();
            if (document.Type == JTokenType.Object) { objects.Add((JObject)document); }
            var changed = false;
            foreach (var item in objects)
            {
                if (context.Operation.Id.StartsWith("mcp-", StringComparison.Ordinal) && (string)item["jsonrpc"] == "2.0")
                {
                    var result = item["result"] as JObject;
                    if (result != null)
                    {
                        var meta = result["_meta"] as JObject ?? new JObject();
                        meta["contentSafety"] = telemetry.DeepClone();
                        result["_meta"] = meta;
                        var structured = result["structuredContent"] as JObject;
                        if (structured != null) { structured["contentSafety"] = telemetry.DeepClone(); }
                        var content = result["content"] as JArray;
                        if (content != null)
                        {
                            var summary = new JObject(new JProperty("contentSafety", telemetry.DeepClone())).ToString(Newtonsoft.Json.Formatting.None);
                            var firstText = content.FirstOrDefault(x => (string)x["type"] == "text") as JObject;
                            if (firstText == null)
                            {
                                content.Add(new JObject(new JProperty("type", "text"), new JProperty("text", summary)));
                            }
                            else
                            {
                                var text = (string)firstText["text"] ?? string.Empty;
                                try
                                {
                                    var json = JObject.Parse(text);
                                    json["contentSafety"] = telemetry.DeepClone();
                                    firstText["text"] = json.ToString(Newtonsoft.Json.Formatting.None);
                                }
                                catch { firstText["text"] = text + "\n\n" + summary; }
                            }
                        }
                        changed = true;
                    }
                    var error = item["error"] as JObject;
                    if (error != null)
                    {
                        var data = error["data"] as JObject ?? new JObject();
                        if (error["data"] != null && error["data"].Type != JTokenType.Object)
                        {
                            data["upstreamData"] = error["data"].DeepClone();
                        }
                        data["contentSafety"] = telemetry.DeepClone();
                        error["data"] = data;
                        changed = true;
                    }
                }
                else
                {
                    item["contentSafety"] = telemetry.DeepClone();
                    changed = true;
                }
            }
            if (!changed) { continue; }
            var updated = document.ToString(Newtonsoft.Json.Formatting.None);
            if (isSse)
            {
                var output = new List<string>();
                var inserted = false;
                foreach (var line in lines)
                {
                    if (line.StartsWith("data:", StringComparison.Ordinal))
                    {
                        if (!inserted) { output.Add("data: " + updated); inserted = true; }
                    }
                    else { output.Add(line); }
                }
                frames[frameIndex] = string.Join("\n", output);
            }
            else { frames[frameIndex] = updated; }
        }
        return string.Join(isSse ? "\n\n" : string.Empty, frames);
    }
